"""Resolve compiled target and catalog step ids from Mantle path frames.

Stack frames store skill / block ids (and a step cursor on ordered blocks),
not compiled ``target_id``. Helpers here derive compiled target / catalog step
ids for callers that still need them (executor, prompts, provenance, correction).
"""

from __future__ import annotations

from typing import Optional

from rasa.dialogue_understanding.stack.frames.flow_stack_frame import UserFlowStackFrame
from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    OrderedBlockStackFrame,
    SkillStackFrame,
)
from rasa.mantle.skills.catalog import (
    _SYNTHETIC_STEP_ID,
)
from rasa.mantle.skills.catalog import (
    target_id_for_frame as compiled_target_id_for_frame,
)

SYNTHETIC_PROSE_STEP_ID = _SYNTHETIC_STEP_ID

MantlePathFrame = UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame


def target_id_for_frame(frame: MantlePathFrame) -> str:
    """Return the compiled target id currently executing *frame*.

    Skill and ordered-block frames use the catalog compiled-id helper. Legacy
    ``UserFlowStackFrame`` entries still carry ``flow_id`` directly.
    """
    if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
        return compiled_target_id_for_frame(frame)
    return frame.flow_id


def catalog_step_id(frame: MantlePathFrame) -> str:
    """Return the catalog step id currently executing *frame*.

    Skill frames persist no ``step_id``; prose always maps to
    :data:`SYNTHETIC_PROSE_STEP_ID`. Ordered-block and user-flow frames use
    their stored cursor.
    """
    if isinstance(frame, SkillStackFrame):
        return SYNTHETIC_PROSE_STEP_ID
    return frame.step_id


def catalog_step_id_or_none(frame: Optional[MantlePathFrame]) -> Optional[str]:
    """Return :func:`catalog_step_id` for *frame*, or ``None`` if absent."""
    if frame is None:
        return None
    return catalog_step_id(frame)


__all__ = [
    "SYNTHETIC_PROSE_STEP_ID",
    "MantlePathFrame",
    "catalog_step_id",
    "catalog_step_id_or_none",
    "target_id_for_frame",
]
